import { describe, expect, it } from 'vitest';
import fixtures from '../../design/vig-motion.fixtures.json';
import {
	VIG_MOTION,
	approach,
	ease,
	entrance,
	pointerTarget,
	pointerTimeConstant,
	pose,
	sway,
	type Easing
} from './vig-motion';

// The expected values come from design/vig-motion.fixtures.json (generated by
// scripts/brand/vig_motion_fixtures.py). norviq-ios financeplanTests/VigMotionTests.swift loads a
// byte copy of the same file, so the web and iOS Vig move alike.

const near = (actual: number, expected: number) =>
	expect(Math.abs(actual - expected)).toBeLessThanOrEqual(fixtures.tolerance);

function nearAll(actual: object, expected: object) {
	const a = actual as Record<string, number>;
	for (const [key, value] of Object.entries(expected as Record<string, number>))
		near(a[key], value);
}

describe('vig motion fixtures', () => {
	it('match the motion data version', () => {
		expect(fixtures.motionVersion).toBe(VIG_MOTION.version);
	});

	it.each(fixtures.ease)('ease $easing at $u', ({ easing, u, expect: want }) => {
		near(ease(easing as Easing, u), want);
	});

	it.each(fixtures.entrance)('entrance at $t s', ({ t, expect: want }) => {
		nearAll(entrance(VIG_MOTION, t), want);
	});

	it.each(fixtures.sway)('sway at $t s', ({ t, expect: want }) => {
		near(sway(VIG_MOTION, t), want);
	});

	it.each(fixtures.pointerTarget)('pointer target at ($x, $y)', ({ x, y, expect: want }) => {
		nearAll(pointerTarget(VIG_MOTION, x, y), want);
	});

	it.each(fixtures.pointerTimeConstant)(
		'pointer time constant, active $active',
		({ active, expect: want }) => {
			near(pointerTimeConstant(VIG_MOTION, active), want);
		}
	);

	it.each(fixtures.approach)(
		'approach $current → $target over $dt s (τ $tau)',
		({ current, target, dt, tau, expect: want }) => {
			near(approach(current, target, dt, tau), want);
		}
	);

	it.each(fixtures.pose)(
		'pose at $t s with pointer ($pointerYaw, $pointerPitch)',
		({ t, pointerYaw, pointerPitch, expect: want }) => {
			nearAll(pose(VIG_MOTION, t, pointerYaw, pointerPitch), want);
		}
	);
});

describe('vig motion limits', () => {
	it('never turns past the yaw limit, so the flat back never shows', () => {
		for (let t = 0; t < 30; t += 0.05) {
			const p = pose(
				VIG_MOTION,
				t,
				VIG_MOTION.pointer.maxYawDegrees,
				VIG_MOTION.pointer.maxPitchDegrees * 2
			);
			expect(Math.abs(p.yawDegrees)).toBeLessThanOrEqual(VIG_MOTION.limits.maxYawDegrees);
			expect(Math.abs(p.pitchDegrees)).toBeLessThanOrEqual(VIG_MOTION.limits.maxPitchDegrees);
		}
	});
});
